changeSet.sql:
CREATE TABLE nexus.t225_tpl_chunks (LIKE nexus.chunks INCLUDING DEFAULTS INCLUDING GENERATED INCLUDING CONSTRAINTS);
CREATE TABLE nexus.t225_tpl_centroids (LIKE nexus.taxonomy_centroids INCLUDING DEFAULTS INCLUDING GENERATED INCLUDING CONSTRAINTS);
CREATE TABLE nexus.t225_tpl_indexes AS
    SELECT i.tablename, i.indexname, i.indexdef
      FROM pg_catalog.pg_indexes i
     WHERE i.schemaname = 'nexus'
       AND i.tablename IN ('chunks', 'taxonomy_centroids')
       AND i.indexdef NOT LIKE 'CREATE UNIQUE%';
DROP TRIGGER trg_service_tokens_create_tenant_partitions ON nexus.service_tokens;
DROP TABLE nexus.chunks CASCADE;
DROP TABLE nexus.taxonomy_centroids CASCADE;
